const crypto = require('crypto');
const items = $input.all();
const verifiedItems = [];

const staticData = $getWorkflowStaticData('node');
if (!staticData.processedMessages || !Array.isArray(staticData.processedMessages)) {
    staticData.processedMessages = []; 
}

for (const item of items) {
    try {
        const body = item.json.body || {};
        const messageId = body.id || ("manual-test-" + Date.now());

        // 1. PHÁT HIỆN TRÙNG LẶP
        if (staticData.processedMessages.includes(messageId)) {
            // CẤP CỜ TRÙNG LẶP: Đẩy ra 1 item để đi tiếp tới cổng IF Node
            verifiedItems.push({ json: { is_duplicate: true } });
            continue;
        }

        // 2. GHI NHỚ ID TIN NHẮN
        staticData.processedMessages.push(messageId);
        if (staticData.processedMessages.length > 50) {
            staticData.processedMessages.shift(); 
        }

        // 3. LOGIC XỬ LÝ BÌNH THƯỜNG
        const fileUuid = crypto.randomUUID();
        const now = new Date();
        const year = now.getFullYear();
        const month = String(now.getMonth() + 1).padStart(2, '0');

        verifiedItems.push({
            json: {
                is_duplicate: false, // Cờ báo hiệu gói tin sạch
                status: "COMMAND_RECEIVED",
                messageId: messageId,
                teamId: body.channelData?.team?.aadGroupId || "Direct-Chat",
                channelId: body.channelData?.channel?.id ? encodeURIComponent(body.channelData.channel.id) : "Direct-Chat",
                sender: body.from?.name || "Unknown Sender",
                fileUuid: fileUuid,
                objectKeyVideo: `raw-video/${year}/${month}/${fileUuid}.mp4`,
                objectKeyImage: `raw-image/${year}/${month}/${fileUuid}.jpg`
            }
        });
    } catch (error) {
        console.error("AI Node Error: ", error.message);
    }
}
return verifiedItems;

