const crypto = require('crypto');
const ACCOUNT_ID = "REDACTED_ROTATE_REQUIRED"; 
const ACCESS_KEY = "REDACTED_ROTATE_REQUIRED";
const SECRET_KEY = "REDACTED_ROTATE_REQUIRED";
const BUCKET = "inventory-ai-inspection-mvp";

const items = $input.all();
const results = [];

// Hàm tái sử dụng để sinh URL
function getPresignedUrl(objectKey) {
    const method = 'PUT';
    const service = 's3';
    const region = 'auto';
    const host = `${ACCOUNT_ID}.r2.cloudflarestorage.com`;
    const endpoint = `https://${host}/${BUCKET}/${objectKey}`;

    const now = new Date();
    const amzDate = now.toISOString().replace(/[:-]|\.\d{3}/g, '');
    const dateStamp = amzDate.substring(0, 8);

    const canonicalUri = `/${BUCKET}/${objectKey}`;
    const canonicalQuerystring = `X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=${ACCESS_KEY}%2F${dateStamp}%2F${region}%2F${service}%2Faws4_request&X-Amz-Date=${amzDate}&X-Amz-Expires=3600&X-Amz-SignedHeaders=host`;
    const canonicalHeaders = `host:${host}\n`;
    const canonicalRequest = `${method}\n${canonicalUri}\n${canonicalQuerystring}\n${canonicalHeaders}\nhost\nUNSIGNED-PAYLOAD`;

    const credentialScope = `${dateStamp}/${region}/${service}/aws4_request`;
    const stringToSign = `AWS4-HMAC-SHA256\n${amzDate}\n${credentialScope}\n${crypto.createHash('sha256').update(canonicalRequest).digest('hex')}`;

    const kDate = crypto.createHmac('sha256', "AWS4" + SECRET_KEY).update(dateStamp).digest();
    const kRegion = crypto.createHmac('sha256', kDate).update(region).digest();
    const kService = crypto.createHmac('sha256', kRegion).update(service).digest();
    const kSigning = crypto.createHmac('sha256', kService).update("aws4_request").digest();
    const signature = crypto.createHmac('sha256', kSigning).update(stringToSign).digest('hex');

    return `${endpoint}?${canonicalQuerystring}&X-Amz-Signature=${signature}`;
}

for (const item of items) {
    // Gọi hàm 2 lần cho 2 định dạng
    results.push({
        json: {
            ...item.json,
            uploadUrlVideo: getPresignedUrl(item.json.objectKeyVideo),
            uploadUrlImage: getPresignedUrl(item.json.objectKeyImage)
        }
    });
}
return results;
